def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    # boxes: 3x3 rings of 3 with 2 center
    seen=[[False]*W for _ in range(H)]
    boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c]:
                # check 3x3 ring
                ring=all(0<=r+i< H and 0<=c+j<W and g[r+i][c+j]==3 for i in (-1,0,1) for j in (-1,1))
                if ring and g[r][c]==2:
                    boxes.append((r,c))
                    for i in range(r-1,r+2):
                        for j in range(c-1,c+2): seen[i][j]=True
    # lines: rows/cols all 0 or 2, mostly 2s
    lines_v=[c for c in range(W) if all(g[r][c] in (0,2) for r in range(H))]
    lines_h=[r for r in range(H) if all(g[r][c] in (0,2) for c in range(W))]
    out=[r[:] for r in g]
    def paint(row, cells):
        for c in cells:
            if out[row][c]==0: out[row][c]=1
    def stamp(cr,ccL):
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==dc==0: continue
                rr,ccc=cr+dr,ccL+dc
                if 0<=rr<H and 0<=ccc<W and out[rr][ccc]!=3: out[rr][ccc]=1
    for (br,bc) in boxes:
        if lines_v:
            for ccL in lines_v:
                if out[br][ccL]!=2 or True:
                    if br-1>=0 and br+1<H and g[br-1][bc]==3 and g[br+1][bc]==3 and g[br][bc-1]==3 and g[br][bc+1]==3:
                        pass
        # determine orientation: lines vertical -> beams horizontal
        if lines_v and not lines_h:
            for ccL in lines_v:
                if out[br][ccL]!=2 and g[br][bc-1]==3 and g[br][bc+1]==3:
                    pass
        # simplify: beam along row br if lines vertical; along col bc if lines horizontal
        for ccL in lines_v:
            if out[br][ccL]==2 or True:
                pass
        # beam paint
        if lines_v:
            for c in range(W):
                if out[br][c]==0: out[br][c]=1
        else:
            for r in range(H):
                if out[r][bc]==0: out[r][bc]=1
        # rings at beam crossings with lines (excluding box cells)
        if lines_v:
            for ccL in lines_v:
                if 0<=ccL<W and out[br][ccL]==2 and not (ccL>=bc-1 and ccL<=bc+1):
                    stamp(br,ccL)
        else:
            for rrL in lines_h:
                if 0<=rrL<H and out[rrL][bc]==2 and not (rrL>=br-1 and rrL<=br+1):
                    stamp(rrL,bc)
    return out

