def f(g):
    out=[r[:] for r in g]; H=len(g);W=len(g[0])
    boxes=[];seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c] and 0<=r-1<H and 0<=c-1<W and g[r-1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3 and g[r+1][c]==3:
                boxes.append((r,c)); 
                for i in (-1,0,1):
                    for j in (-1,0,1): seen[r+i][c+j]=True
    midrows={br for br,_ in boxes}; midcols={bc for _,bc in boxes}
    def on_mid(r,c): return r in midrows or c in midcols
    for br,bc in boxes:
        # middle row beams toward vertical lines
        for ccL in sorted(vlines):
            if ccL==bc: continue
            sgn=1 if ccL>bc else -1
            c=bc+sgn
            while c!=ccL and 0<=c<W:
                if out[br][c]==0: out[br][c]=1
                c+=sgn
        # middle col beams toward horizontal lines
        for rrL in sorted(hlines):
            if rrL==br: continue
            sgn=1 if rrL>br else -1
            r=br+sgn
            while r!=rrL and 0<=r<H:
                if out[r][bc]==0: out[r][bc]=1
                r+=sgn
    # copies: corridor between two bracketing lines
    for br,bc in boxes:
        cands=[]
        for (a,b) in itertools.combinations(sorted(vlines),2):
            if a<=bc<=b: cands.append(('h',a,b,bc))
        for (a,b) in itertools.combinations(sorted(hlines),2):
            if a<=br<=b: cands.append(('v',a,b,br))
        for typ,L1,L2,ax in cands:
            d=L2-L1
            for sgn in (1,-1):
                if sgn==1:
                    r0,r1=br-d,br
                    c0,c1=bc-d,bc
                else:
                    r0,r1=br,br+d
                    c0,c1=bc,bc+d
                # clip
                r0=max(r0,0); r1=min(r1,H-1); c0=max(c0,0); c1=min(c1,W-1)
                if r0>r1 or c0>c1: continue
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1):
                        if out[r][c]==2 or out[r][c]==0: out[r][c]=1
    # revert line cells on box middle rows/cols to 2
    for r in range(H):
        for c in range(W):
            if out[r][c]==1 and on_mid(r,c) and g[r][c] in (0,2): out[r][c]=2
    return out

