from collections import Counter
def boxes_and_lines(g):
    H=len(g);W=len(g[0])
    boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and r in (0,H-1) or False: pass
    # boxes: 3x3 rings of 3 with 2 center
    for r in range(H):
        for c in range(W):
            if g[r][c]==3:
                if 0<=r-1<H and 0<=c-1<W and 0<=r+1<H and 0<=c+1<W and \
                   g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3:
                    # ensure full ring and center is 2
                    cells=[(dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)]
                    if all(g[r+dr][c+dc]==3 for dr,dc in cells) and g[r][c]==2:
                        boxes.append((r,c))
    hlines={r for r in range(H) if all(g[r][c]==2 for c in range(W))}
    vlines={c for c in range(W) if all(g[r][c]==2 for r in range(H))}
    return boxes,hlines,vlines

