for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    gi=G[k+' input']; go=G[k+' output']
    H=len(gi);W=len(gi[0])
    # objects: boxes (3rings), vertical 2-lines (full column of 2s outside boxes? check)
    boxes=[]; lines=[]
    for r in range(H):
        for c in range(W):
            if gi[r][c]==2:
                if gi[r][c+1]!=2 and gi[r][c-1]!=2:  # isolated 2 -> line candidate
                    pass
    # detect boxes: 3-ring with 2 center
    for r in range(H-1):
        for c in range(W-1):
            if gi[r][c]==2 and gi[r+1][c]==3 and gi[r+1][c+1]==3 and gi[r+1][c-1]==3:
                boxes.append((r+1,c+1))
    # vertical lines: columns where gi[row][c]==2 for many rows, excluding box centers
    for c in range(W):
        tw=sum(1 for r in range(H) if gi[r][c]==2)
        if tw>H//2 and c not in [bc for _,bc in boxes]:
            lines.append(('v',c,tw))
    # horizontal lines
    for r in range(H):
        tw=sum(1 for c in range(W) if gi[r][c]==2)
