        for cc in sorted(S):
            for lo,hi in spans:
                for rr in range(lo,hi):
                    if g[rr][cc]!=2 and out[rr][cc]!=3: out[rr][cc]=1
        for r,c in boxes:
            mr=r+1
            for cc in range(w):
                if g[mr][cc]!=2 and out[mr][cc]!=3: out[mr][cc]=1
    # cross-stamp: each box's recolored pattern into the other's rectangle
    def rec(p): return tuple(1 if v==3 else v for v in p)
    for i,(r1,c1) in enumerate(boxes):
